<?php $__env->startSection('content'); ?>
<div class="page-heading"><div><div class="eyebrow">ASSET IDENTIFICATION</div><h1>Scan asset QR / barcode</h1><p>Use a compatible device camera to scan a QR label, or enter an asset tag or serial number.</p></div></div>
<div class="row g-3"><div class="col-lg-6"><div class="panel p-3"><div class="scanner-frame"><video id="scannerVideo" playsinline></video><div class="scanner-guide"></div></div><div class="d-flex gap-2 mt-3"><button id="startScanner" class="btn btn-primary">Start camera</button><button id="stopScanner" class="btn btn-light border" disabled>Stop camera</button></div><p id="scannerMessage" class="small text-secondary mt-3 mb-0">Camera scanning requires a secure origin (HTTPS or localhost) and browser BarcodeDetector support.</p></div></div><div class="col-lg-6"><div class="panel p-3"><form method="GET" action="<?php echo e(route('scan.index')); ?>"><label class="form-label">Asset tag or serial number</label><div class="input-group"><input class="form-control" name="tag" value="<?php echo e(request('tag')); ?>" placeholder="e.g. IT-2026-0001" required><button class="btn btn-primary">Find asset</button></div></form><?php if(request()->filled('tag')): ?><?php if($asset): ?><div class="scan-result mt-4"><span class="status-pill <?php echo e($asset->status); ?>"><?php echo e(str_replace('_',' ',$asset->status)); ?></span><h3 class="mt-2"><?php echo e($asset->name); ?></h3><div class="mono text-secondary"><?php echo e($asset->asset_tag); ?></div><p class="small text-secondary"><?php echo e($asset->brand); ?> <?php echo e($asset->model); ?> · <?php echo e($asset->category?->name); ?></p><a class="btn btn-outline-primary" href="<?php echo e(route('inventory.show',['assets',$asset->id])); ?>">Open asset record</a></div><?php else: ?><div class="alert alert-warning mt-4">No asset matched that identifier.</div><?php endif; ?>
<?php endif; ?></div></div></div>
<?php $__env->stopSection(); ?>
<?php $__env->startPush('scripts'); ?><script>
(()=>{const video=document.getElementById('scannerVideo'),start=document.getElementById('startScanner'),stop=document.getElementById('stopScanner'),msg=document.getElementById('scannerMessage');let stream=null,active=false,detector=null;const shutdown=()=>{active=false;stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;start.disabled=false;stop.disabled=true;};stop.addEventListener('click',shutdown);start.addEventListener('click',async()=>{if(!('BarcodeDetector' in window)){msg.textContent='This browser does not support native QR scanning. Use the asset tag search field or a USB barcode scanner.';return;}try{detector=new BarcodeDetector({formats:['qr_code','code_128','code_39','ean_13']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;await video.play();active=true;start.disabled=true;stop.disabled=false;msg.textContent='Camera active. Point it at an asset label.';const scan=async()=>{if(!active)return;try{const codes=await detector.detect(video);if(codes.length){const value=codes[0].rawValue;if(value.startsWith(location.origin)){location.href=value;return;}location.href='<?php echo e(route('scan.index')); ?>?tag='+encodeURIComponent(value);return;}}catch(e){}requestAnimationFrame(scan);};scan();}catch(e){msg.textContent='Camera could not be started: '+e.message;shutdown();}});window.addEventListener('pagehide',shutdown);})();
</script><?php $__env->stopPush(); ?>

